hook_source = (ROOT / 'module/src/com/refresh165/Hook.java').read_text(encoding='utf-8')
window_start = hook_source.index('private static void hookWindowPreferredMode')
window_end = hook_source.index('private static boolean isKeyguardLocked', window_start)
window_hook = hook_source[window_start:window_end]
final_start = hook_source.index('private static void hookFinalDisplayMode')
final_end = hook_source.index('// ================================================================= 前台切换即时信号', final_start)
final_hook = hook_source[final_start:final_end]
assert 'PanelRate.panelRateId' not in window_hook and 'win-pref-systemui-panel' not in window_hook, 'shade must not rewrite candidate/window vote'
assert 'PanelRate.finalModeId' in final_hook, 'shade override must remain at final display-mode seam'

with tempfile.TemporaryDirectory(prefix='refresh165-regression-') as tmp:
    base = Path(tmp)
    files = []
    for name, text in SOURCES.items():
        dest = base / name
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(text, encoding='utf-8')
        files.append(str(dest))
    for name in ['HookStatus', 'ThermalGuard', 'PerApp', 'PolicyRef', 'MinFpsState', 'Reapply', 'VideoRate', 'PeakRepair', 'PanelRate']:
        files.append(str(ROOT / 'module/src/com/refresh165' / (name + '.java')))
    subprocess.run([str(JAVA_HOME / 'bin/javac'), '--release', '11', '-encoding', 'UTF-8', '-d', str(base)] + files, check=True)
    subprocess.run([str(JAVA_HOME / 'bin/java'), '-cp', str(base), 'com.refresh165.Regression'], check=True)
